function normalizePayload(value) {
  if (value == null) return {};
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return {};
    try {
      return JSON.parse(trimmed);
    } catch {
      return { _raw_body: trimmed };
    }
  }
  if (typeof value === 'object') return value;
  return { value };
}
function collapseWhitespace(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}
function stripLegalSuffix(value) {
  return collapseWhitespace(value)
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function normalizeHomepage(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname = String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  return hostname && hostname.includes('.') ? 'https://' + hostname + '/' : '';
}
function extractDomain(value) {
  const homepage = normalizeHomepage(value);
  const match = homepage.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
}

const source = Object.prototype.hasOwnProperty.call($json || {}, 'body') ? $json.body : $json;
const body = normalizePayload(source);
if (!body || !body.Id) {
  throw new Error(`Worker payload missing Id: ${JSON.stringify(body).slice(0, 500)}`);
}
const companyName = collapseWhitespace(body.company_name || '');
if (!companyName) {
  throw new Error(`Worker payload missing company_name for Id ${body.Id}`);
}
const candidateHomepage = normalizeHomepage(body.candidate_homepage || body.website_url || '');
const candidateDomain = extractDomain(body.candidate_domain || candidateHomepage || body.best_url || body.url_validated || '');
const searchLoose = stripLegalSuffix(companyName) || companyName;

return {
  json: {
    ...body,
    company_name: companyName,
    company_name_original: companyName,
    company_name_normalized: companyName,
    search_exact: '"' + companyName.replace(/"/g, '') + '"',
    search_loose: searchLoose,
    candidate_homepage: candidateHomepage,
    candidate_domain: candidateDomain,
  },
};

