function normalizeText(value) {
  return String(value || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
}
function tokenize(value) {
  return normalizeText(value).split(/\s+/).filter(Boolean);
}
function unique(values) {
  return [...new Set(values.filter(Boolean))];
}
function parseUrlParts(value) {
  const raw = String(value || '').trim();
  if (!raw) return null;
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)([^?#]*)/i);
  if (!match) return null;
  const hostname = String(match[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  if (!hostname || !hostname.includes('.')) return null;
  let path = String(match[2] || '/').trim().toLowerCase();
  if (!path) path = '/';
  if (!path.startsWith('/')) path = '/' + path;
  return { origin: 'https://' + hostname + '/', hostname, path, depth: path.split('/').filter(Boolean).length };
}
function extractSearchResults(payload) {
  const rawCandidates = [payload?.results, payload?.json?.results, payload?.response?.results, payload?.body?.results, payload?.data?.results, payload?.organic, payload?.json?.organic, payload?.response?.organic, payload?.body?.organic, payload?.data?.organic];
  for (const candidate of rawCandidates) {
    if (Array.isArray(candidate) && candidate.length) return candidate;
  }
  for (const candidate of [payload?.body, payload?.data]) {
    if (typeof candidate === 'string' && candidate.trim()) {
      try {
        const parsed = JSON.parse(candidate);
        if (Array.isArray(parsed.results) && parsed.results.length) return parsed.results;
        if (Array.isArray(parsed.organic) && parsed.organic.length) return parsed.organic;
      } catch {}
    }
  }
  return [];
}
function mergeResults(...lists) {
  const seen = new Set();
  const merged = [];
  for (const list of lists) {
    for (const result of Array.isArray(list) ? list : []) {
      const key = String(result?.url || result?.link || result?.homepage || '').trim().toLowerCase();
      if (!key || seen.has(key)) continue;
      seen.add(key);
      merged.push(result);
    }
  }
  return merged;
}
function significantTokens(value) {
  return tokenize(value).filter((token) => !['and','the','of','for','pte','ltd','limited','private','singapore','sg','holdings','group','groups','company','companies','corp','corporation','llp','inc','sdn','bhd'].includes(token));
}
function compact(value) {
  return significantTokens(value).join('');
}
function tokenOverlap(tokens, text) {
  return tokens.filter((token) => token && text.includes(token)).length;
}
const BLOCKED_HOSTS = ['facebook.com','linkedin.com','instagram.com','twitter.com','x.com','tiktok.com','youtube.com','yelp.com','practo.com','tripadvisor.com','foursquare.com','yellowpages.com.sg','healthhub.sg','moh.gov.sg','gobusiness.gov.sg','acra.gov.sg','classpcn.sg','pcds.sg'];
const DIRECTORY_HOSTS = ['streetdirectory.com','wherecrowded.sg','locanto.sg','yalwa.sg','recordowl.com','findhealthclinics.com','doctorxdentist.com'];
const MARKETPLACE_HOSTS = ['foodpanda.sg','grab.com','amazon.com'];
const NEWS_HOSTS = ['straitstimes.com','todayonline.com','channelnewsasia.com','businessinsider.com','techinasia.com'];
const ASSOCIATION_HOSTS = ['sma.org.sg','ams.edu.sg'];
const NEGATIVE_TEXT = /\b(directory|listing|profile|review|marketplace|aggregator|map|directions|portal|government|association|share price|stock quote|forum|reddit|quora|news)\b/i;
const OFFICIAL_TEXT = /\b(official|homepage|website|contact us|about us|our services|book appointment|our doctors|our team|our clinic|medical centre|medical center|clinic|hospital|dental|specialist|family medicine|healthcare|practice|group)\b/i;
const SAME_ORG_TEXT = /\b(contact us|book appointment|opening hours|located at|our doctors|our services|our clinic|our centre|our center|patient|patients|find us|visit us|clinic locations|our locations)\b/i;

const input = $('Normalize Input').item.json || {};
const primaryResults = extractSearchResults($('Search Homepage Exact').item.json);
const fallbackResults = extractSearchResults($('Search Homepage Fallback').item.json);
const syntheticSeed = input.candidate_homepage ? [{ title: input.company_name_normalized || input.company_name || '', url: input.candidate_homepage, snippet: 'seed homepage candidate' }] : [];
const results = mergeResults(syntheticSeed, primaryResults, fallbackResults);
const exactNeedle = normalizeText(input.company_name_normalized || input.company_name || '');
const looseNeedle = normalizeText(input.search_loose || input.company_name_normalized || '');
const companyTokens = unique(significantTokens(input.company_name_normalized || '').concat(significantTokens(input.search_loose || '')));
const compactTargets = unique([compact(input.company_name_normalized || ''), compact(input.search_loose || '')].filter(Boolean));
const seedDomain = String(input.candidate_domain || '').replace(/^www\./i, '').toLowerCase().trim();

function scoreResult(parsed, title, snippet) {
  const titleNorm = normalizeText(title);
  const snippetNorm = normalizeText(snippet);
  const hostNorm = normalizeText(String(parsed.hostname || '').replace(/[.-]/g, ' '));
  const hostCore = String(parsed.hostname || '').replace(/\.(com|org|net|gov|edu)(\.sg)?$/i, '').replace(/\.sg$/i, '').replace(/[^a-z0-9]/g, '');
  const titleOverlap = tokenOverlap(companyTokens, titleNorm);
  const snippetOverlap = tokenOverlap(companyTokens, snippetNorm);
  const hostOverlap = tokenOverlap(companyTokens, hostNorm + ' ' + hostCore);
  const exactCompactHost = compactTargets.some((target) => target && (hostCore === target || hostCore.includes(target) || target.includes(hostCore)));
  const titleExact = Boolean(exactNeedle && titleNorm.includes(exactNeedle));
  const titleNear = !titleExact && titleOverlap >= Math.min(Math.max(companyTokens.length - 1, 2), 4);
  const snippetExact = Boolean((exactNeedle && snippetNorm.includes(exactNeedle)) || (looseNeedle && looseNeedle !== exactNeedle && snippetNorm.includes(looseNeedle)));
  const snippetNear = !snippetExact && snippetOverlap >= Math.min(Math.max(companyTokens.length - 1, 2), 4);
  const officialSignal = OFFICIAL_TEXT.test([title, snippet, parsed.path].join(' '));
  const sameOrgSignal = SAME_ORG_TEXT.test([title, snippet].join(' '));
  const healthcareSignal = /\b(clinic|medical|health|care|dental|specialist|practice|doctor|family|hospital|centre|center|pharmacy|laboratory)\b/i.test([title, snippet, parsed.hostname].join(' '));
  let score = 0;
  if (titleExact) score += 36;
  else if (titleNear) score += 22;
  if (snippetExact) score += 14;
  else if (snippetNear) score += 8;
  if (exactCompactHost) score += 22;
  else if (hostOverlap >= 2) score += 16;
  else if (hostOverlap === 1) score += 8;
  if (seedDomain && parsed.hostname === seedDomain) score += 18;
  if (officialSignal) score += 10;
  if (healthcareSignal) score += 6;
  if (sameOrgSignal) score += 8;
  if (parsed.depth <= 1) score += 4;
  if (NEGATIVE_TEXT.test([title, snippet, parsed.path].join(' '))) score -= 16;
  if (parsed.depth >= 4) score -= 10;
  if (parsed.path.includes('/news') || parsed.path.includes('/blog') || parsed.path.includes('/press')) score -= 14;
  if (MARKETPLACE_HOSTS.some((host) => parsed.hostname === host || parsed.hostname.endsWith('.' + host))) score -= 38;
  if (NEWS_HOSTS.some((host) => parsed.hostname === host || parsed.hostname.endsWith('.' + host))) score -= 28;
  if (ASSOCIATION_HOSTS.some((host) => parsed.hostname === host || parsed.hostname.endsWith('.' + host))) score -= 18;
  return {
    score,
    signals: [
      titleExact ? 'title_exact' : '',
      titleNear ? 'title_near' : '',
      snippetExact ? 'snippet_exact' : '',
      snippetNear ? 'snippet_near' : '',
      exactCompactHost ? 'domain_exact' : hostOverlap ? 'domain_overlap' : '',
      seedDomain && parsed.hostname === seedDomain ? 'seed_domain' : '',
      officialSignal ? 'official' : '',
      healthcareSignal ? 'healthcare' : '',
      sameOrgSignal ? 'same_org' : ''
    ].filter(Boolean)
  };
}

const grouped = new Map();
for (const [index, result] of results.entries()) {
  const rawUrl = String(result?.url || result?.link || result?.homepage || '').trim();
  const parsed = parseUrlParts(rawUrl);
  if (!parsed) continue;
  if (BLOCKED_HOSTS.some((host) => parsed.hostname === host || parsed.hostname.endsWith('.' + host))) continue;
  if (DIRECTORY_HOSTS.some((host) => parsed.hostname === host || parsed.hostname.endsWith('.' + host))) continue;
  const title = String(result?.title || '').trim();
  const snippet = String(result?.content || result?.snippet || '').trim();
  const { score, signals } = scoreResult(parsed, title, snippet);
  if (score < 14) continue;
  const current = grouped.get(parsed.origin) || {
    homepage: parsed.origin,
    hostname: parsed.hostname,
    raw_url: rawUrl,
    title,
    snippet,
    rank: index + 1,
    score: 0,
    hit_count: 0,
    signals: [],
  };
  current.hit_count += 1;
  if (score > current.score) {
    current.score = score;
    current.raw_url = rawUrl;
    current.title = title;
    current.snippet = snippet;
    current.rank = index + 1;
  }
  current.signals = unique(current.signals.concat(signals));
  grouped.set(parsed.origin, current);
}

const candidates = [...grouped.values()]
  .map((candidate) => ({
    ...candidate,
    score: candidate.score + Math.min(8, Math.max(candidate.hit_count - 1, 0) * 4),
  }))
  .sort((a, b) => (b.score || 0) - (a.score || 0) || a.rank - b.rank)
  .slice(0, 12);

const top = candidates[0] || null;
const second = candidates[1] || null;
const gap = top && second ? Number(top.score || 0) - Number(second.score || 0) : Number(top?.score || 0);
const skipllm = Boolean(top && ((top.score >= 72) || (top.score >= 56 && gap >= 12) || (candidates.length === 1 && top.score >= 44)));
const candidateSummary = candidates.slice(0, 8).map((candidate, index) => `${index + 1}. score=${candidate.score} | hits=${candidate.hit_count} | ${candidate.homepage} | ${candidate.title} | ${candidate.signals.join(',')}`).join('\n');
const rawResultsSummary = results.slice(0, 8).map((result, index) => `${index + 1}. ${String(result?.title || '').trim()} | ${String(result?.url || result?.link || result?.homepage || '').trim()} | ${String(result?.content || result?.snippet || '').replace(/\s+/g, ' ').trim().slice(0, 180)}`).join('\n');
const rawSample = results.slice(0, 5).map((result) => String(result?.url || result?.link || result?.homepage || '')).filter(Boolean).join(' | ');

return {
  json: {
    best_url: skipllm && top ? top.homepage : '',
    skipllm,
    top_score: top ? Number(top.score || 0) : 0,
    search_results_count: results.length,
    raw_sample: rawSample,
    raw_results_summary: rawResultsSummary,
    candidate_summary: candidateSummary,
    candidates,
  },
};

