function normalizeWorkflowUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const lower = raw.toLowerCase();
  if (['reject','rejected','none','duplicate','url rejected'].includes(lower)) return '';
  const match = raw.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname = String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  return hostname && hostname.includes('.') ? 'https://' + hostname + '/' : '';
}
function canonicalDomain(value) {
  const raw = normalizeWorkflowUrl(value);
  if (!raw) return '';
  const match = raw.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
}
function unique(values) {
  return [...new Set(values.filter(Boolean))];
}
const prepared = $('Score URL Candidates').item.json || {};
const candidates = Array.isArray(prepared.candidates) ? prepared.candidates : [];
const candidateHomepages = unique(candidates.map((candidate) => normalizeWorkflowUrl(candidate.homepage || candidate.raw_url || '')));
const preparedBest = normalizeWorkflowUrl(prepared.best_url || '');
const topCandidate = candidates[0] || {};
const pickedRaw = String($json.choices?.[0]?.message?.content || $json.body?.choices?.[0]?.message?.content || '').trim();
const pickedHomepage = normalizeWorkflowUrl(pickedRaw);
let bestUrl = '';
let resolvedBy = 'none';
if (prepared.skipllm === true && preparedBest) {
  bestUrl = preparedBest;
  resolvedBy = 'deterministic';
} else if (pickedHomepage && candidateHomepages.includes(pickedHomepage)) {
  bestUrl = pickedHomepage;
  resolvedBy = 'llm';
} else if (preparedBest && candidateHomepages.includes(preparedBest)) {
  bestUrl = preparedBest;
  resolvedBy = 'scored';
} else if (candidateHomepages.length === 1 && Number(topCandidate.score || 0) >= 30) {
  bestUrl = candidateHomepages[0];
  resolvedBy = 'single';
}
return { json: {
  best_url: bestUrl || 'none',
  canonical_homepage: bestUrl,
  canonical_domain: canonicalDomain(bestUrl),
  candidate_count: candidateHomepages.length,
  resolved_by: resolvedBy
} };

function canonicalDomain(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const match = raw.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1] || raw || '').replace(/^www\./i, '').toLowerCase().trim();
}
const currentId = Number($('Normalize Input').item.json.Id || 0);
const currentDomain = String($('Finalize URL').item.json.canonical_domain || '').trim().toLowerCase();
const list = Array.isArray($json.list) ? $json.list : [];
const comparable = list
  .map((row) => ({
    ...row,
    comparable_domain: canonicalDomain(row.candidate_domain || row.url_validated || row.best_url || ''),
    comparable_status: String(row.status || '').trim().toLowerCase(),
  }))
  .filter((row) => row.comparable_domain && row.comparable_domain === currentDomain)
  .filter((row) => row.comparable_status !== 'failed');

const ownerId = [currentId]
  .concat(comparable.map((row) => Number(row.Id || 0)).filter((id) => Number.isInteger(id) && id > 0))
  .sort((a, b) => a - b)[0] || currentId;

return {
  json: {
    canonical_domain: currentDomain,
    owner_id: ownerId,
    duplicate_of_id: ownerId !== currentId ? ownerId : '',
    winner: Boolean(currentDomain) && ownerId === currentId,
    claim_count: comparable.length,
  },
};

function normalizeWorkflowUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const lower = raw.toLowerCase();
  if (['reject','rejected','none','duplicate','url rejected'].includes(lower)) return '';
  return /^https?:\/\//i.test(raw) ? raw : '';
}
function domainFromUrl(value) {
