  const hostname = String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  return hostname.includes('.') ? hostname : '';
}
const websiteContent = ($('Crawl4AI - Scrape').item.json.website_content || '').substring(0, 8000);
const companyName = String(($('Normalize Input').item.json.choices?.[0]?.message?.content || $('Normalize Input').item.json.body?.choices?.[0]?.message?.content || $('Normalize Input').item.json.company_name || '')).trim();
const validatedUrl = normalizeWorkflowUrl($('Finalize URL').item.json.best_url || '');
const contactDomain = domainFromUrl(validatedUrl);
const body = {
  model: 'minimax/minimax-m2.7',
  temperature: 0,
  messages: [{
    role: 'user',
    content:
      'Website content: ' + websiteContent + '\n' +
      'Company name: ' + companyName + '\n\n' +
      'This is a Singapore organisation that may use a branch or location suffix and may belong to a parent brand or group.\n' +
      'Return a JSON object with exactly these two keys:\n' +
      '{"company_homepage_name":"","parent_company":""}\n\n' +
      'Definitions:\n' +
      '- company_homepage_name = the clean operating brand or organisation name shown on the site. Remove branch, estate, or location suffixes like Bishan, Bedok, Hougang, Bukit Merah, etc. Keep the operating brand shown on the site.\n' +
      '- parent_company = a distinct higher-level parent/group/holding company only if clearly different from company_homepage_name. If no distinct parent exists, return company_homepage_name again.\n\n' +
      'Rules:\n' +
      '- Works for healthcare, social service, SaaS, and other private organisations.\n' +
      '- Prefer the Singapore operating brand shown on the official site.\n' +
      '- Do not invent a parent company.\n' +
      '- If the company itself is the top-level brand, set parent_company equal to company_homepage_name.\n\n' +
      'Output: valid JSON only. No markdown.'
  }]
};
return { json: {
  requestBody: body,
  best_url: validatedUrl,
  url_validated: validatedUrl,
  contact_domain: contactDomain
} };

function cleanText(value) {
  const raw = String(value ?? '').trim();
