}
const prep = $('Prep Company Facts').item.json || {};
const response = ($json.choices?.[0]?.message?.content || '').trim();
const fallbackName = cleanText($('Normalize Input').item.json.company_name || '');
let data = {};
try {
  const fence = String.fromCharCode(96).repeat(3);
  const cleaned = response.replace(new RegExp(fence + 'json\n?', 'g'), '').replace(new RegExp(fence + '\n?', 'g'), '').trim();
  data = JSON.parse(cleaned);
